from itertools import islice, groupby, cycle


def batched(iterable, n):
    it = iter(iterable)
    while True:
        batch = tuple(islice(it, n))
        if not batch:
            return
        yield batch


def unique_justseen(iterable):
    for key, _ in groupby(iterable):
        yield key


def roundrobin(*iterables):
    num_active = len(iterables)
    nexts = cycle(iter(it) for it in iterables)
    while num_active:
        try:
            for nxt in nexts:
                result = next(nxt)
                yield result
        except StopIteration:
            num_active -= 1
            nexts = cycle(islice(nexts, num_active))
